function cheapestThreeCuts(nums: number[]): number {
  let best = Infinity;
  for (let i = 1; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      best = Math.min(best, nums[0] + nums[i] + nums[j]);
  return best;
}

