function cheapestThreeCuts(nums: number[]): number {
  let first = Infinity, second = Infinity;
  for (let i = 1; i < nums.length; i++) {
    const v = nums[i];
    if (v < first) { second = first; first = v; }
    else if (v < second) second = v;
  }
  return nums[0] + first + second;
}

